// Generated by scripts/build-n2-reading-notes.mts. Each day loads on demand.
import type { DayNotes } from "./types";

export type { DayNotes, SentenceNote } from "./types";

const loaders: Record<string, () => Promise<DayNotes>> = {
	"2-6": () => import("./w2d6").then((m) => m.notes),
};

export function hasN2ReadingNotes(week: number, day: number): boolean {
	return `${week}-${day}` in loaders;
}

export function loadN2ReadingNotes(week: number, day: number): Promise<DayNotes> | undefined {
	return loaders[`${week}-${day}`]?.();
}
